impl Drop for DawUi {
    fn drop(&mut self) {
        self.stop_project_playback();
        if let Some(session) = self.audio_recording.take() {
            if session.capture_active
                && let Some(engine) = self.audio_engine.as_ref()
            {
                engine.stop_input_recording();
            }
            let _ = session.worker.join();
        }
        if let Some(session) = self.sample_editor_recording.take() {
            if session.capture_active
                && let Some(engine) = self.audio_engine.as_ref()
            {
                engine.stop_input_recording();
            }
            let _ = session.worker.join();
        }
        for worker in self.audio_render_workers.drain(..) {
            let _ = worker.worker.join();
        }
        for render in self.song_render_workers.drain(..) {
            let _ = render.worker.join();
        }
        if let Some(stream) = self.pending_vst3_stream.take() {
            self.vst3_workers.push(stream);
        }
        for worker in self.vst3_workers.drain(..) {
            let _ = worker.join();
        }
        if let Some(backup) = self.pending_backup_write.take() {
            let _ = backup.worker.join();
        }
    }
}

fn empty_view(ui: &mut egui::Ui, message: &str) {
    ui.centered_and_justified(|ui| {
        ui.label(egui::RichText::new(message).size(18.0).color(MUTED));
    });
}

fn plugin_state_warning_suffix(warnings: &[String]) -> String {
    if warnings.is_empty() {
        String::new()
    } else {
        format!(
            " · VST3 state kept from its previous save for {}",
            warnings.join("; ")
        )
    }
}

fn layer_child_selection_label(child_ids: &[u16], channels: &[ChannelSummary]) -> String {
    if child_ids.is_empty() {
        return "No child channels".to_owned();
    }
    child_ids
        .iter()
        .map(|child_id| {
            channels
                .iter()
                .find(|channel| channel.id() == *child_id)
                .map(|channel| {
                    format!(
                        "{} (ID {child_id})",
                        channel.display_name().unwrap_or("(unnamed channel)")
                    )
                })
                .unwrap_or_else(|| format!("Missing channel (ID {child_id})"))
        })
        .collect::<Vec<_>>()
        .join(", ")
}

fn update_layer_child_selection(child_ids: &mut Vec<u16>, child_id: u16, selected: bool) {
    if selected {
        if !child_ids.contains(&child_id) {
            child_ids.push(child_id);
        }
    } else {
        child_ids.retain(|id| *id != child_id);
    }
}

fn update_channel_rack_selection(
    channel_ids: &[u16],
    selected: &mut BTreeSet<u16>,
    anchor: &mut Option<u16>,
    channel_id: u16,
    additive: bool,
    extend_range: bool,
) {
    let Some(channel_index) = channel_ids.iter().position(|id| *id == channel_id) else {
        return;
    };
    if extend_range {
        let anchor_index = anchor
            .and_then(|anchor_id| channel_ids.iter().position(|id| *id == anchor_id))
            .unwrap_or(channel_index);
        if !additive {
            selected.clear();
        }
        selected.extend(
            channel_ids
                .iter()
                .take(anchor_index.max(channel_index) + 1)
                .skip(anchor_index.min(channel_index))
                .copied(),
        );
        if anchor.is_none() {
            *anchor = Some(channel_id);
        }
    } else if additive {
        if selected.contains(&channel_id) {
            if selected.len() > 1 {
                selected.remove(&channel_id);
            }
        } else {
            selected.insert(channel_id);
        }
        *anchor = Some(channel_id);
    } else {
        selected.clear();
        selected.insert(channel_id);
        *anchor = Some(channel_id);
    }
}

fn channel_type_icon_description(channel_type: Option<ChannelType>) -> String {
    match channel_type {
        Some(ChannelType::Sampler) => "Sampler channel".to_owned(),
        Some(ChannelType::Native) => "Generator channel".to_owned(),
        Some(ChannelType::Layer) => "Layer channel".to_owned(),
        Some(ChannelType::Instrument) => "Instrument channel".to_owned(),
        Some(ChannelType::Automation) => "Automation channel".to_owned(),
        Some(ChannelType::Unknown(raw)) => format!("Unknown channel type {raw}"),
        None => "Unclassified channel".to_owned(),
    }
}

fn paint_channel_type_icon(
    painter: &egui::Painter,
    rect: egui::Rect,
    channel_type: Option<ChannelType>,
    color: Color32,
) {
    let icon_rect = rect.shrink(2.0);
    painter.rect_filled(icon_rect, 3.0, PANEL_DARK);
    painter.rect_stroke(
        icon_rect,
        3.0,
        Stroke::new(1.0, color),
        egui::StrokeKind::Inside,
    );
    let center = icon_rect.center();
    match channel_type {
        Some(ChannelType::Sampler) => {
            for (offset, half_height) in [(-4.5, 3.0), (-1.5, 6.0), (1.5, 4.0), (4.5, 2.0)] {
                painter.line_segment(
                    [
                        egui::pos2(center.x + offset, center.y - half_height),
                        egui::pos2(center.x + offset, center.y + half_height),
                    ],
                    Stroke::new(1.4, color),
                );
            }
        }
        Some(ChannelType::Native) => {
            let points = [
                egui::pos2(center.x - 6.0, center.y),
                egui::pos2(center.x - 3.0, center.y - 3.0),
                egui::pos2(center.x, center.y + 3.0),
                egui::pos2(center.x + 3.0, center.y - 3.0),
                egui::pos2(center.x + 6.0, center.y),
            ];
            for pair in points.windows(2) {
                painter.line_segment([pair[0], pair[1]], Stroke::new(1.4, color));
            }
        }
        Some(ChannelType::Layer) => {
            for (offset_x, offset_y) in [(-2.0, -2.0), (2.0, 2.0)] {
                painter.rect_stroke(
                    egui::Rect::from_center_size(
                        center + Vec2::new(offset_x, offset_y),
                        Vec2::new(9.0, 7.0),
                    ),
                    1.0,
                    Stroke::new(1.2, color),
                    egui::StrokeKind::Inside,
                );
            }
        }
        Some(ChannelType::Instrument) => {
            for (offset, half_height) in [(-4.5, 2.0), (-1.5, 4.0), (1.5, 3.0), (4.5, 2.0)] {
                painter.line_segment(
                    [
                        egui::pos2(center.x + offset, center.y - half_height),
                        egui::pos2(center.x + offset, center.y + half_height),
                    ],
                    Stroke::new(1.4, color),
                );
            }
        }
        Some(ChannelType::Automation) => {
            let points = [
                egui::pos2(center.x - 5.0, center.y + 4.0),
                egui::pos2(center.x - 1.0, center.y + 1.0),
                egui::pos2(center.x + 2.0, center.y - 4.0),
                egui::pos2(center.x + 5.0, center.y - 2.0),
            ];
            for pair in points.windows(2) {
                painter.line_segment([pair[0], pair[1]], Stroke::new(1.4, color));
            }
            for point in [points[0], points[2], points[3]] {
                painter.circle_filled(point, 1.5, color);
            }
        }
        Some(ChannelType::Unknown(raw)) => {
            painter.text(
                center,
                Align2::CENTER_CENTER,
                format!("{raw:X}"),
                FontId::proportional(9.0),
                color,
            );
        }
        None => {
            painter.text(
                center,
                Align2::CENTER_CENTER,
                "?",
                FontId::proportional(11.0),
                color,
            );
        }
    }
}

fn piano_roll_note_group_members(
    pattern: &Pattern,
    pattern_id: u16,
    channel_id: u16,
    channel_note_index: usize,
) -> Vec<(u16, u16, usize)> {
    let Some(note) = pattern
        .notes
        .iter()
        .filter(|note| note.channel_id == channel_id)
        .nth(channel_note_index)
    else {
        return Vec::new();
    };
    if note.group == 0 {
        return vec![(pattern_id, channel_id, channel_note_index)];
    }
    let group = note.group;
    pattern
        .notes
        .iter()
        .filter(|note| note.channel_id == channel_id)
        .enumerate()
        .filter(|(_, note)| note.group == group)
        .map(|(index, _)| (pattern_id, channel_id, index))
        .collect()
}

fn piano_roll_odd_note_selection(
    pattern: &Pattern,
    pattern_id: u16,
    channel_id: u16,
    main_grid_ticks: u32,
) -> Vec<(u16, u16, usize)> {
    let main_grid_ticks = main_grid_ticks.max(1);
    let mut off_grid_groups = BTreeSet::<(u16, usize)>::new();
    for (note_index, note) in pattern
        .notes
        .iter()
        .filter(|note| note.channel_id == channel_id)
        .enumerate()
    {
        if note.position % main_grid_ticks != 0 {
            let group_key = if note.group == 0 {
                (0, note_index)
            } else {
                (note.group, 0)
            };
            off_grid_groups.insert(group_key);
        }
    }

    pattern
        .notes
        .iter()
        .filter(|note| note.channel_id == channel_id)
        .enumerate()
        .filter(|(note_index, note)| {
            let group_key = if note.group == 0 {
                (0, *note_index)
            } else {
                (note.group, 0)
            };
            off_grid_groups.contains(&group_key)
        })
        .map(|(note_index, _)| (pattern_id, channel_id, note_index))
        .collect()
}

fn piano_roll_overlap_note_selection(
    pattern: &Pattern,
    pattern_id: u16,
    channel_id: u16,
    stacked_only: bool,
) -> Vec<(u16, u16, usize)> {
    let channel_notes = pattern
        .notes
        .iter()
        .filter(|note| note.channel_id == channel_id)
        .enumerate();
    let mut selected_indices = BTreeSet::new();

    if stacked_only {
        let mut notes_by_span = BTreeMap::<(u32, u32), Vec<(usize, u16)>>::new();
        for (note_index, note) in channel_notes {
            if note.length > 0 {
                notes_by_span
                    .entry((note.position, note.length))
                    .or_default()
                    .push((note_index, note.key));
            }
        }
        for notes in notes_by_span.values() {
            piano_roll_select_component_above_lowest(notes, &mut selected_indices);
        }
    } else {
        let mut intervals = pattern
            .notes
            .iter()
            .filter(|note| note.channel_id == channel_id)
            .enumerate()
            .filter_map(|(note_index, note)| {
                (note.length > 0).then_some((
                    u64::from(note.position),
                    u64::from(note.position) + u64::from(note.length),
                    note_index,
                    note.key,
                ))
            })
            .collect::<Vec<_>>();
        intervals.sort_by_key(|(start, end, note_index, _)| (*start, *end, *note_index));

        let mut component = Vec::new();
        let mut component_end = 0_u64;
        for (start, end, note_index, key) in intervals {
            if !component.is_empty() && start >= component_end {
                piano_roll_select_component_above_lowest(&component, &mut selected_indices);
                component.clear();
            }
            if component.is_empty() {
                component_end = end;
            } else {
                component_end = component_end.max(end);
            }
            component.push((note_index, key));
        }
        piano_roll_select_component_above_lowest(&component, &mut selected_indices);
    }

    let selected_groups = pattern
        .notes
        .iter()
        .filter(|note| note.channel_id == channel_id)
        .enumerate()
        .filter(|(note_index, _)| selected_indices.contains(note_index))
        .map(|(_, note)| note.group)
        .filter(|group| *group != 0)
        .collect::<BTreeSet<_>>();

    pattern
        .notes
        .iter()
        .filter(|note| note.channel_id == channel_id)
        .enumerate()
        .filter(|(note_index, note)| {
            selected_indices.contains(note_index)
                || (note.group != 0 && selected_groups.contains(&note.group))
        })
        .map(|(note_index, _)| (pattern_id, channel_id, note_index))
        .collect()
}

fn piano_roll_select_component_above_lowest(
    notes: &[(usize, u16)],
    selected_indices: &mut BTreeSet<usize>,
) {
    let Some((lowest_index, _)) = notes
        .iter()
        .min_by_key(|(note_index, key)| (*key, *note_index))
    else {
        return;
    };
    selected_indices.extend(
        notes
            .iter()
            .filter_map(|(note_index, _)| (note_index != lowest_index).then_some(*note_index)),
    );
}

fn piano_roll_selection_time_range(
    pattern: &Pattern,
    pattern_id: u16,
    selected_notes: &BTreeSet<(u16, u16, usize)>,
) -> Option<(u32, u32)> {
    let mut start = u32::MAX;
    let mut end = 0_u32;
    let mut found_note = false;
    let mut channel_indices = BTreeMap::<u16, usize>::new();
    for note in &pattern.notes {
        let note_index = channel_indices.entry(note.channel_id).or_default();
        if selected_notes.contains(&(pattern_id, note.channel_id, *note_index)) {
            let note_end = note.position.saturating_add(note.length);
            if note_end > note.position {
                start = start.min(note.position);
                end = end.max(note_end);
                found_note = true;
            }
        }
        *note_index += 1;
    }
    found_note.then_some((start, end))
}

fn piano_roll_time_range_note_selection(
    pattern: &Pattern,
    pattern_id: u16,
    channel_id: u16,
    start: u32,
    end: u32,
) -> Vec<(u16, u16, usize)> {
    if end <= start {
        return Vec::new();
    }

    let channel_notes = pattern
        .notes
        .iter()
        .filter(|note| note.channel_id == channel_id)
        .collect::<Vec<_>>();
    let mut selected_indices = BTreeSet::new();
    let mut selected_groups = BTreeSet::new();
    for (note_index, note) in channel_notes.iter().enumerate() {
        if (start..end).contains(&note.position) {
            selected_indices.insert(note_index);
            if note.group != 0 {
                selected_groups.insert(note.group);
            }
        }
    }

    channel_notes
        .iter()
        .enumerate()
        .filter(|(note_index, note)| {
            selected_indices.contains(note_index)
                || (note.group != 0 && selected_groups.contains(&note.group))
        })
        .map(|(note_index, _)| (pattern_id, channel_id, note_index))
        .collect()
}

fn piano_roll_pitch_range_note_selection(
    pattern: &Pattern,
    pattern_id: u16,
    channel_id: u16,
    first_key: u16,
    last_key: u16,
) -> Vec<(u16, u16, usize)> {
    let low_key = first_key.min(last_key);
    let high_key = first_key.max(last_key);
    let channel_notes = pattern
        .notes
        .iter()
        .filter(|note| note.channel_id == channel_id)
        .collect::<Vec<_>>();
    let mut selected_indices = BTreeSet::new();
    let mut selected_groups = BTreeSet::new();
    for (note_index, note) in channel_notes.iter().enumerate() {
        if (low_key..=high_key).contains(&note.key) {
            selected_indices.insert(note_index);
            if note.group != 0 {
                selected_groups.insert(note.group);
            }
        }
    }

    channel_notes
        .iter()
        .enumerate()
        .filter(|(note_index, note)| {
            selected_indices.contains(note_index)
                || (note.group != 0 && selected_groups.contains(&note.group))
        })
        .map(|(note_index, _)| (pattern_id, channel_id, note_index))
        .collect()
}

fn piano_roll_key_at_y(
    pointer_y: f32,
    grid_top: f32,
    key_height: f32,
    key_low: u16,
    key_high: u16,
) -> u16 {
    let row = ((pointer_y - grid_top).max(0.0) / key_height.max(f32::EPSILON))
        .floor()
        .clamp(0.0, f32::from(key_high.saturating_sub(key_low))) as u16;
    key_high.saturating_sub(row)
}

fn piano_roll_shift_time_range(start: u32, end: u32, direction: TimeSelectionShift) -> (u32, u32) {
    let width = end.saturating_sub(start);
    let start = match direction {
        TimeSelectionShift::Previous => start.saturating_sub(width),
        TimeSelectionShift::Next => start.saturating_add(width),
    };
    (start, start.saturating_add(width))
}

fn piano_roll_time_tick_at_x(
    pointer_x: f32,
    grid_left: f32,
    tick_scale: f32,
    snap_ticks: u32,
) -> u32 {
    let tick = ((pointer_x - grid_left).max(0.0) / tick_scale.max(f32::EPSILON))
        .round()
        .clamp(0.0, u32::MAX as f32) as i64;
    snap_note_tick(tick, snap_ticks, 0)
}

fn piano_roll_slice_line_cut_x(
    start: egui::Pos2,
    end: egui::Pos2,
    rect: egui::Rect,
) -> Option<f32> {
    let dx = end.x - start.x;
    let dy = end.y - start.y;
    if dx.abs() <= f32::EPSILON && dy.abs() <= f32::EPSILON {
        return None;
    }
    let mut first_t = 0.0f32;
    let mut last_t = 1.0f32;
    for (p, q) in [
        (-dx, start.x - rect.left()),
        (dx, rect.right() - start.x),
        (-dy, start.y - rect.top()),
        (dy, rect.bottom() - start.y),
    ] {
        if p == 0.0 {
            if q < 0.0 {
                return None;
            }
            continue;
        }
        let t = q / p;
        if p < 0.0 {
            if t > last_t {
                return None;
            }
            first_t = first_t.max(t);
        } else {
            if t < first_t {
                return None;
            }
            last_t = last_t.min(t);
        }
    }
    (first_t <= last_t).then_some(start.x + dx * ((first_t + last_t) * 0.5))
}

fn piano_roll_time_range_from_drag(
    start_tick: u32,
    current_tick: u32,
    snap_ticks: u32,
) -> (u32, u32) {
    let first_tick = start_tick.min(current_tick);
    let last_tick = start_tick.max(current_tick);
    let start = snap_note_tick(i64::from(first_tick), snap_ticks, 0);
    let end = snap_note_tick(i64::from(last_tick), snap_ticks, start)
        .max(start.saturating_add(snap_ticks.max(1)));
    (start, end)
}

fn piano_roll_duplicate_offset(
    first_position: u32,
    last_end: u32,
    time_selection: Option<(u32, u32)>,
) -> u32 {
    time_selection
        .map(|(start, end)| end.saturating_sub(start))
        .filter(|width| *width > 0)
        .unwrap_or_else(|| last_end.saturating_sub(first_position).max(1))
}

fn piano_roll_random_note_selection(
    pattern: &Pattern,
    pattern_id: u16,
    channel_id: u16,
    selected: &BTreeSet<(u16, u16, usize)>,
    select_more: bool,
    seed: u64,
) -> Option<BTreeSet<(u16, u16, usize)>> {
    let mut groups = BTreeMap::<(u16, usize), Vec<(u16, u16, usize)>>::new();
    for (note_index, note) in pattern
        .notes
        .iter()
        .filter(|note| note.channel_id == channel_id)
        .enumerate()
    {
        let group_key = if note.group == 0 {
            (0, note_index)
        } else {
            (note.group, 0)
        };
        groups
            .entry(group_key)
            .or_default()
            .push((pattern_id, channel_id, note_index));
    }

    let candidates = groups
        .into_values()
        .filter(|members| !select_more || members.iter().all(|member| !selected.contains(member)))
        .collect::<Vec<_>>();
    let group_index = piano_roll_random_index(candidates.len(), seed)?;
    let mut result = if select_more {
        selected.clone()
    } else {
        BTreeSet::new()
    };
    result.extend(candidates[group_index].iter().copied());
    Some(result)
}

fn piano_roll_random_index(length: usize, seed: u64) -> Option<usize> {
    if length == 0 {
        return None;
    }

    let mut value = seed.wrapping_add(0x9E37_79B9_7F4A_7C15);
    value = (value ^ (value >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
    value = (value ^ (value >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
    value ^= value >> 31;
    Some((value % length as u64) as usize)
}

fn piano_roll_note_nudge_edit(
    note: &PatternNote,
    tick_delta: i64,
    semitone_delta: i32,
) -> PatternNoteEdit {
    let position = (tick_delta != 0).then(|| {
        let amount = tick_delta.unsigned_abs().min(u64::from(u32::MAX)) as u32;
        if tick_delta < 0 {
            note.position.saturating_sub(amount)
        } else {
            note.position.saturating_add(amount)
        }
    });
    let key = (semitone_delta != 0).then(|| {
        i32::from(note.key)
            .saturating_add(semitone_delta)
            .clamp(0, 131) as u16
    });
    PatternNoteEdit {
        position: position.filter(|position| *position != note.position),
        key: key.filter(|key| *key != note.key),
        ..PatternNoteEdit::default()
    }
}

fn piano_roll_discard_length_edit(
    note: &PatternNote,
    minimum_length_ticks: u32,
) -> Option<PatternNoteEdit> {
    let length = minimum_length_ticks.max(1);
    (note.length != length).then_some(PatternNoteEdit {
        length: Some(length),
        ..PatternNoteEdit::default()
    })
}

fn piano_roll_color_group_note_ids(
    pattern: &Pattern,
    pattern_id: u16,
    channel_id: u16,
    color_group: u8,
) -> Vec<(u16, u16, usize)> {
    let color_group = color_group & 0x0f;
    pattern
        .notes
        .iter()
        .filter(|note| note.channel_id == channel_id)
        .enumerate()
        .filter(|(_, note)| note.midi_channel & 0x0f == color_group)
        .map(|(note_index, _)| (pattern_id, channel_id, note_index))
        .collect()
}

fn toggle_piano_roll_note_group_selection(
    selected: &mut BTreeSet<(u16, u16, usize)>,
    members: &[(u16, u16, usize)],
    additive: bool,
) -> bool {
    let remove =
        additive && !members.is_empty() && members.iter().all(|member| selected.contains(member));
    if remove {
        for member in members {
            selected.remove(member);
        }
    } else {
        selected.extend(members.iter().copied());
    }
    !remove
}

fn update_piano_roll_box_selection(
    pattern: &Pattern,
    pattern_id: u16,
    channel_id: u16,
    enclosed_note_indices: &[usize],
    additive: bool,
    selected: &mut BTreeSet<(u16, u16, usize)>,
) {
    let mut processed_groups = BTreeSet::new();
    for note_index in enclosed_note_indices {
        let group = pattern
            .notes
            .iter()
            .filter(|note| note.channel_id == channel_id)
            .nth(*note_index)
            .map_or(0, |note| note.group);
        let key = if group == 0 {
            (group, *note_index)
        } else {
            (group, 0)
        };
        if !processed_groups.insert(key) {
            continue;
        }
        let members = piano_roll_note_group_members(pattern, pattern_id, channel_id, *note_index);
        toggle_piano_roll_note_group_selection(selected, &members, additive);
    }
}

fn next_piano_roll_note_group(pattern: &Pattern, channel_id: u16) -> Option<u16> {
    let used_groups = pattern
        .notes
        .iter()
        .filter(|note| note.channel_id == channel_id && note.group != 0)
        .map(|note| note.group)
        .collect::<BTreeSet<_>>();
    (1..=u16::MAX).find(|group| !used_groups.contains(group))
}

fn automation_point_screen_position(
    point: &AutomationPoint,
    plot_rect: egui::Rect,
    visible_beats: f64,
) -> egui::Pos2 {
    let beat_fraction = if point.position_beats().is_finite() {
        (point.position_beats() / visible_beats).clamp(0.0, 1.0) as f32
    } else {
        0.0
    };
    let value_fraction = if point.value().is_finite() {
        point.value().clamp(0.0, 1.0) as f32
    } else {
        0.5
    };
    egui::pos2(
        egui::lerp(plot_rect.left()..=plot_rect.right(), beat_fraction),
        egui::lerp(plot_rect.bottom()..=plot_rect.top(), value_fraction),
    )
}

fn index_browser_folders(roots: Vec<PathBuf>, all_roots: bool) -> Result<BrowserIndex, String> {
    let mut entries = Vec::new();
    let mut seen_paths = BTreeSet::new();
    let mut scan_entries = 0usize;
    let mut truncated = false;
    let mut unavailable_roots = Vec::new();

    'roots: for root in &roots {
        let mut directories = VecDeque::from([root.clone()]);
        'tree: while let Some(directory) = directories.pop_front() {
            let children = match fs::read_dir(&directory) {
                Ok(children) => children,
                Err(error) if directory == *root => {
                    if all_roots {
                        unavailable_roots.push(root.clone());
                        break 'tree;
                    }
                    return Err(format!("Could not search {}: {error}", root.display()));
                }
                Err(_) => continue,
            };
            for child in children {
                let Ok(child) = child else {
                    continue;
                };
                let Ok(file_type) = child.file_type() else {
                    continue;
                };
                let path = child.path();
                let name = child.file_name().to_string_lossy().into_owned();
                if browser_entry_is_hidden(&name) {
                    continue;
                }
                if scan_entries >= MAX_BROWSER_RECURSIVE_SCAN_ENTRIES {
                    truncated = true;
                    break 'roots;
                }
                scan_entries += 1;
                if file_type.is_dir() {
                    directories.push_back(path);
                } else if file_type.is_file()
                    && browser_file_kind(&path).is_some()
                    && seen_paths.insert(path.clone())
                {
                    let relative_path = path.strip_prefix(root).unwrap_or(&path);
                    let name = if all_roots {
                        let root_name = root
                            .file_name()
                            .map(|name| name.to_string_lossy().into_owned())
                            .unwrap_or_else(|| root.display().to_string());
                        format!("{root_name}/{}", relative_path.display())
                    } else {
                        relative_path.to_string_lossy().into_owned()
                    };
                    entries.push(BrowserEntry {
                        name,
                        path,
                        is_directory: false,
                    });
                }
            }
        }
    }

    entries.sort_by(|left, right| {
        left.name
            .to_lowercase()
            .cmp(&right.name.to_lowercase())
            .then_with(|| left.path.cmp(&right.path))
    });
    Ok(BrowserIndex {
        roots,
        all_roots,
        entries,
        truncated,
        unavailable_roots,
    })
}

fn browser_entry_is_hidden(name: &str) -> bool {
    name.starts_with('.')
}

fn default_browser_directory() -> PathBuf {
    let home = std::env::var_os("HOME")
        .or_else(|| std::env::var_os("USERPROFILE"))
        .map(PathBuf::from)
        .filter(|path| path.is_dir());
    browser_factory_packs_directory()
        .or_else(|| {
            home.as_ref()
                .map(|path| path.join("Music"))
                .filter(|path| path.is_dir())
        })
        .or(home)
        .or_else(|| std::env::current_dir().ok())
        .unwrap_or_default()
}

fn browser_favorites_file() -> Option<PathBuf> {
    let root = if cfg!(target_os = "windows") {
        std::env::var_os("APPDATA").map(PathBuf::from).or_else(|| {
            std::env::var_os("USERPROFILE")
                .map(PathBuf::from)
                .map(|home| home.join("AppData").join("Roaming"))
        })
    } else if cfg!(target_os = "macos") {
        std::env::var_os("HOME")
            .map(PathBuf::from)
            .map(|home| home.join("Library").join("Application Support"))
    } else {
        std::env::var_os("XDG_CONFIG_HOME")
            .map(PathBuf::from)
            .or_else(|| {
                std::env::var_os("HOME")
                    .map(PathBuf::from)
                    .map(|home| home.join(".config"))
            })
    }?;
    Some(root.join("fl-studio-rebuild").join("browser-favorites.txt"))
}

