    #[test]
    fn piano_roll_chord_detection_names_inversions_and_common_extensions() {
        let note = |key, channel_id| PatternNote {
            position: 96,
            channel_id,
            key,
            ..PatternNote::default()
        };
        let first_inversion = vec![note(52, 2), note(60, 2), note(67, 2), note(36, 3)];
        let major_ninth = vec![
            note(60, 2),
            note(64, 2),
            note(67, 2),
            note(71, 2),
            note(74, 2),
        ];
        let c_sixth = vec![note(60, 2), note(64, 2), note(67, 2), note(69, 2)];
        let a_minor_seventh = vec![note(57, 2), note(60, 2), note(64, 2), note(67, 2)];

        assert_eq!(detect_chord_name(&first_inversion, 2, 96), "C major/E");
        assert_eq!(detect_chord_name(&major_ninth, 2, 96), "C maj9");
        assert_eq!(detect_chord_name(&c_sixth, 2, 96), "C 6");
        assert_eq!(detect_chord_name(&a_minor_seventh, 2, 96), "A m7");
    }

    #[test]
    fn piano_roll_advanced_chord_stamps_use_their_chromatic_intervals() {
        let cases = [
            (PianoRollChordStamp::Major6, vec![60, 64, 67, 69]),
            (PianoRollChordStamp::Minor6, vec![60, 63, 67, 69]),
            (PianoRollChordStamp::Add9, vec![60, 64, 67, 74]),
            (PianoRollChordStamp::MinorAdd9, vec![60, 63, 67, 74]),
            (PianoRollChordStamp::Diminished7, vec![60, 63, 66, 69]),
            (PianoRollChordStamp::HalfDiminished7, vec![60, 63, 66, 70]),
            (PianoRollChordStamp::MinorMajor7, vec![60, 63, 67, 71]),
            (PianoRollChordStamp::Dominant7Flat5, vec![60, 64, 66, 70]),
            (PianoRollChordStamp::Dominant7Sharp5, vec![60, 64, 68, 70]),
            (
                PianoRollChordStamp::Dominant7Flat9,
                vec![60, 64, 67, 70, 73],
            ),
            (
                PianoRollChordStamp::Dominant7Sharp9,
                vec![60, 64, 67, 70, 75],
            ),
            (PianoRollChordStamp::Dominant9, vec![60, 64, 67, 70, 74]),
            (PianoRollChordStamp::Major9, vec![60, 64, 67, 71, 74]),
            (PianoRollChordStamp::Minor9, vec![60, 63, 67, 70, 74]),
            (
                PianoRollChordStamp::Dominant11,
                vec![60, 64, 67, 70, 74, 77],
            ),
            (PianoRollChordStamp::Minor11, vec![60, 63, 67, 70, 74, 77]),
            (
                PianoRollChordStamp::Dominant13,
                vec![60, 64, 67, 70, 74, 77, 81],
            ),
        ];

        for (stamp, expected) in cases {
            assert_eq!(
                stamp.pitches(60, PianoRollScale::None, 0),
                expected,
                "{}",
                stamp.label(),
            );
        }
    }

    #[test]
    fn piano_roll_top_down_chord_stamps_keep_the_clicked_pitch_on_top() {
        assert_eq!(
            PianoRollChordStamp::TopDownTriad.pitches(64, PianoRollScale::Major, 0),
            vec![57, 60, 64],
        );
        assert_eq!(
            PianoRollChordStamp::TopDownSeventh.pitches(64, PianoRollScale::Major, 0),
            vec![53, 57, 60, 64],
        );
        assert_eq!(
            PianoRollChordStamp::TopDownTriad.pitches(69, PianoRollScale::Major, 2),
            vec![62, 66, 69],
        );
        assert_eq!(
            PianoRollChordStamp::TopDownTriad.pitches(64, PianoRollScale::None, 0),
            vec![57, 60, 64],
            "an unset scale falls back to the selected key's major scale",
        );
        assert_eq!(
            PianoRollChordStamp::TopDownTriad.pitches(0, PianoRollScale::Major, 0),
            Vec::<u16>::new(),
            "the lowest MIDI key cannot fit a chord underneath it",
        );
    }

    #[test]
    fn piano_roll_scale_chord_stamps_follow_non_c_key_roots() {
        assert_eq!(
            PianoRollChordStamp::ScaleTriad.pitches(69, PianoRollScale::Major, 2),
            vec![69, 73, 76],
            "A is the fifth scale degree in D major",
        );
        assert_eq!(
            PianoRollChordStamp::ScaleSeventh.pitches(69, PianoRollScale::Major, 2),
            vec![69, 73, 76, 79],
        );
        assert_eq!(
            PianoRollChordStamp::ScaleTriad.pitches(60, PianoRollScale::NaturalMinor, 9),
            vec![60, 64, 67],
            "C is the third scale degree in A natural minor",
        );
    }

