    #[test]
    fn piano_roll_scale_snap_chooses_the_nearest_in_range_note() {
        assert_eq!(
            snap_piano_roll_key_to_scale(61, PianoRollScale::Major, 0, 36, 83),
            60,
            "an equal-distance tie resolves downward",
        );
        assert_eq!(
            snap_piano_roll_key_to_scale(63, PianoRollScale::Major, 0, 36, 83),
            62,
        );
        assert_eq!(
            snap_piano_roll_key_to_scale(61, PianoRollScale::Major, 0, 61, 70),
            62,
            "the result stays within the visible keyboard range",
        );
        assert_eq!(
            snap_piano_roll_key_to_scale(61, PianoRollScale::None, 0, 36, 83),
            61,
            "None accepts every pitch",
        );
    }

    #[test]
    fn midi_record_scale_snap_changes_only_out_of_scale_pitches() {
        let mut notes = vec![
            PatternNote {
                key: 61,
                velocity: 93,
                length: 48,
                ..PatternNote::default()
            },
            PatternNote {
                key: 67,
                velocity: 72,
                length: 96,
                ..PatternNote::default()
            },
            PatternNote {
                key: 127,
                velocity: 101,
                length: 24,
                ..PatternNote::default()
            },
        ];
        snap_recorded_midi_notes_to_scale(
            &mut notes,
            DetectedPianoRollScale {
                root: 0,
                scale: PianoRollScale::Major,
            },
        );

        assert_eq!(
            notes.iter().map(|note| note.key).collect::<Vec<_>>(),
            vec![60, 67, 127]
        );
        assert_eq!(
            notes.iter().map(|note| note.velocity).collect::<Vec<_>>(),
            vec![93, 72, 101]
        );
        assert_eq!(
            notes.iter().map(|note| note.length).collect::<Vec<_>>(),
            vec![48, 96, 24]
        );
    }

