    fn built_in_midi_controller_templates_use_documented_cc_mappings() {
        let templates = built_in_midi_controller_templates();
        assert_eq!(templates.len(), 14);
        assert_eq!(templates[0].name, "General MIDI Ch. 1 (CC 7 + CC 64)");
        assert!(templates[0].built_in);
        assert_eq!(
            templates[0].output_gain,
            Some(MidiControllerCcBinding {
                channel: 0,
                controller: 7,
            })
        );
        assert_eq!(
            templates[0].play_pause,
            Some(MidiControllerCcBinding {
                channel: 0,
                controller: 64,
            })
        );
        assert_eq!(templates[1].name, "MIDI Expression Ch. 1 (CC 11)");
        assert!(templates[1].built_in);
        assert_eq!(
            templates[1].output_gain,
            Some(MidiControllerCcBinding {
                channel: 0,
                controller: 11,
            })
        );
        assert_eq!(templates[1].play_pause, None);
        assert_eq!(templates[2].name, "X-TOUCH MINI Preset A (Ch. 11)");
        assert!(templates[2].built_in);
        assert_eq!(
            templates[2].output_gain,
            Some(MidiControllerCcBinding {
                channel: 10,
                controller: 9,
            })
        );
        assert_eq!(templates[2].play_pause, None);
        assert_eq!(templates[3].name, "X-TOUCH MINI Preset B (Ch. 11)");
        assert!(templates[3].built_in);
        assert_eq!(
            templates[3].output_gain,
            Some(MidiControllerCcBinding {
                channel: 10,
                controller: 10,
            })
        );
        assert_eq!(templates[3].play_pause, None);
        assert_eq!(
            templates[4].name,
            "X-TOUCH COMPACT Preset Layer A Fader 9 (Ch. 1)"
        );
        assert!(templates[4].built_in);
        assert_eq!(
            templates[4].output_gain,
            Some(MidiControllerCcBinding {
                channel: 0,
                controller: 9,
            })
        );
        assert_eq!(templates[4].play_pause, None);
        assert_eq!(templates[5].name, "Akai MIDImix Master Fader (Ch. 1)");
        assert!(templates[5].built_in);
        assert_eq!(
            templates[5].output_gain,
            Some(MidiControllerCcBinding {
                channel: 0,
                controller: 62,
            })
        );
        assert_eq!(templates[5].play_pause, None);
        assert_eq!(templates[6].name, "Akai MIDImix Fader 1 (Ch. 1)");
        assert!(templates[6].built_in);
        assert_eq!(
            templates[6].output_gain,
            Some(MidiControllerCcBinding {
                channel: 0,
                controller: 19,
            })
        );
        assert_eq!(templates[6].play_pause, None);
        for (template, (fader, controller)) in templates[7..].iter().zip([
            (2, 23),
            (3, 27),
            (4, 31),
            (5, 49),
            (6, 53),
            (7, 57),
            (8, 61),
        ]) {
            assert_eq!(template.name, format!("Akai MIDImix Fader {fader} (Ch. 1)"));
            assert!(template.built_in);
            assert_eq!(
                template.output_gain,
                Some(MidiControllerCcBinding {
                    channel: 0,
                    controller,
                })
            );
            assert_eq!(template.play_pause, None);
        }
        assert!(serialize_midi_controller_templates(&templates).is_empty());
    }

