    #[test]
    fn playlist_group_range_includes_parent_and_following_child_tracks() {
        let tracks = (1..=4)
            .map(|id| PlaylistTrack {
                id,
                state_byte: None,
                name: None,
                enabled: Some(true),
                grouped: Some(matches!(id, 2 | 3)),
                state_bytes: vec![0; 70],
            })
            .collect::<Vec<_>>();

        assert_eq!(playlist_track_group_range(1, &tracks), Some((1, 3)));
        assert_eq!(playlist_track_group_range(2, &tracks), Some((1, 3)));
        assert_eq!(playlist_track_group_range(3, &tracks), Some((1, 3)));
        assert_eq!(playlist_track_group_range(4, &tracks), Some((4, 4)));
        assert_eq!(playlist_track_group_range(5, &tracks), None);
        assert_eq!(playlist_group_parent_ids(&tracks), vec![1]);

        let collapsed = BTreeSet::from([1]);
        assert!(!playlist_track_is_hidden(1, &tracks, &collapsed, true));
        assert!(playlist_track_is_hidden(2, &tracks, &collapsed, true));
        assert!(playlist_track_is_hidden(3, &tracks, &collapsed, true));
        assert!(!playlist_track_is_hidden(4, &tracks, &collapsed, true));
        assert!(!playlist_track_is_hidden(5, &tracks, &collapsed, true));
        assert!(!playlist_track_is_hidden(2, &tracks, &collapsed, false));
        assert!(!playlist_track_is_hidden(3, &tracks, &collapsed, false));
    }

    #[test]
    fn playlist_seek_tick_converts_to_song_frames() {
        let tempo_map = PlaylistTempoMap::constant(96, 120.0).unwrap();
        assert_eq!(
            playlist_seek_tick_to_frame(384, &tempo_map, 48_000),
            Ok(96_000)
        );
        assert_eq!(playlist_seek_tick_to_frame(0, &tempo_map, 48_000), Ok(0));
        assert!(playlist_seek_tick_to_frame(384, &tempo_map, 0).is_err());
    }

